    out.push({ texto: tok + (pct ? '%' : ''), candidatos: pct ? cands.concat(cands.map(function (c) { return c / 100 })) : cands, pct: pct, pequena: pequena, ignorable: esAnio || esOrden || pequena, estructural: esAnio || esOrden })
